BEGIN;
-- Match stable IDs AND the original Arabic so an edited passage never acquires
-- another text's meaning. Preserve all previously reviewed editorial work.
WITH catalog(id,arabic,bn_title,bn_text,ur_title,ur_text,ar_title) AS (VALUES
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a06','الْحَمْدُ لِلَّهِ','খাওয়ার পর','সমস্ত প্রশংসা আল্লাহর।','کھانے کے بعد','سب تعریف اللہ کے لیے ہے۔','بعد الطعام'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a09','الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا','ঘুম থেকে ওঠার পর','সমস্ত প্রশংসা আল্লাহর, যিনি আমাদের জীবন দিয়েছেন।','جاگنے کے بعد','سب تعریف اللہ کے لیے ہے جس نے ہمیں زندگی دی۔','عند الاستيقاظ'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a15','أَسْتَغْفِرُ اللَّهَ','আস্তাগফিরুল্লাহ','আমি আল্লাহর কাছে ক্ষমা চাই।','استغفار','میں اللہ سے بخشش مانگتا ہوں۔','الاستغفار'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a05','بِسْمِ اللَّهِ','খাওয়ার আগে','আল্লাহর নামে।','کھانے سے پہلے','اللہ کے نام سے۔','قبل الطعام'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a08','بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي','ঘুমের আগে','হে আমার রব, আপনার নামেই আমি শয্যায় পাশ রাখছি।','سونے سے پہلے','اے میرے رب، تیرے نام سے میں اپنا پہلو بستر پر رکھتا ہوں۔','قبل النوم'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a14','رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ','ক্ষমা ও তওবার দোয়া','হে আমার রব, আমাকে ক্ষমা করুন এবং আমার তওবা কবুল করুন। নিশ্চয়ই আপনিই তওবা কবুলকারী, পরম দয়ালু।','بخشش اور توبہ کی دعا','اے میرے رب، مجھے بخش دے اور میری توبہ قبول فرما۔ بے شک تو ہی توبہ قبول کرنے والا، نہایت رحم والا ہے۔','دعاء المغفرة والتوبة'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a12','رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ','দুনিয়া ও আখিরাতের কল্যাণের দোয়া','হে আমাদের রব, আমাদের দুনিয়ায় কল্যাণ দিন, আখিরাতেও কল্যাণ দিন এবং আমাদের আগুনের শাস্তি থেকে রক্ষা করুন।','دنیا اور آخرت کی بھلائی کی دعا','اے ہمارے رب، ہمیں دنیا میں بھلائی دے اور آخرت میں بھی بھلائی دے، اور ہمیں آگ کے عذاب سے بچا۔','دعاء خير الدنيا والآخرة'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a21','رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ','হিদায়াতের দোয়া','হে আমাদের রব, আমাদের হিদায়াত দেওয়ার পর আমাদের অন্তর বক্র করবেন না এবং আপনার পক্ষ থেকে আমাদের রহমত দান করুন। নিশ্চয়ই আপনিই মহাদাতা।','ہدایت کی دعا','اے ہمارے رب، ہمیں ہدایت دینے کے بعد ہمارے دل ٹیڑھے نہ کر اور ہمیں اپنے پاس سے رحمت عطا فرما۔ بے شک تو ہی بہت عطا کرنے والا ہے۔','دعاء الثبات على الهداية'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a17','اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي','সুস্থতার দোয়া','হে আল্লাহ, আমার দেহে সুস্থতা দিন। হে আল্লাহ, আমার শ্রবণশক্তিতে সুস্থতা দিন। হে আল্লাহ, আমার দৃষ্টিশক্তিতে সুস্থতা দিন।','عافیت کی دعا','اے اللہ، میرے جسم کو عافیت دے۔ اے اللہ، میری سماعت کو عافیت دے۔ اے اللہ، میری بینائی کو عافیت دے۔','دعاء العافية'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11','اللَّهُمَّ بَارِكْ لِي فِيمَا رَزَقْتَنِي','রিজিকে বরকতের দোয়া','হে আল্লাহ, আপনি আমাকে যা রিজিক দিয়েছেন তাতে আমার জন্য বরকত দিন।','رزق میں برکت کی دعا','اے اللہ، جو رزق تو نے مجھے دیا ہے اس میں میرے لیے برکت دے۔','دعاء البركة في الرزق'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a22','اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ','সরল পথের দোয়া','আমাদের সরল পথ দেখান।','سیدھے راستے کی دعا','ہمیں سیدھا راستہ دکھا۔','دعاء الهداية إلى الصراط المستقيم'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a18','اللَّهُمَّ رَبَّ النَّاسِ أَذْهِبِ الْبَأْسَ وَاشْفِ أَنْتَ الشَّافِي لَا شِفَاءَ إِلَّا شِفَاؤُكَ شِفَاءً لَا يُغَادِرُ سَقَمًا','অসুস্থ ব্যক্তির জন্য দোয়া','হে আল্লাহ, মানুষের রব, কষ্ট দূর করুন এবং সুস্থতা দিন। আপনিই আরোগ্যদাতা। আপনার আরোগ্য ছাড়া কোনো আরোগ্য নেই। এমন আরোগ্য দিন যা কোনো রোগ বাকি রাখে না।','مریض کے لیے دعا','اے اللہ، لوگوں کے رب، تکلیف دور فرما اور شفا دے۔ تو ہی شفا دینے والا ہے۔ تیری شفا کے سوا کوئی شفا نہیں۔ ایسی شفا عطا فرما جو کوئی بیماری باقی نہ چھوڑے۔','الدعاء للمريض'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a10','اللَّهُمَّ اكْفِنِي بِحَلاَلِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ','হালাল রিজিকের দোয়া','হে আল্লাহ, আপনার হালাল দিয়ে আমাকে আপনার হারাম থেকে বাঁচিয়ে রাখুন এবং আপনার অনুগ্রহে আপনি ছাড়া অন্য সবার মুখাপেক্ষিতা থেকে আমাকে মুক্ত করুন।','حلال رزق کی دعا','اے اللہ، اپنے حلال کے ذریعے مجھے اپنے حرام سے بچا، اور اپنے فضل سے مجھے اپنے سوا ہر ایک سے بے نیاز کر دے۔','دعاء الكفاية بالحلال'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a16','رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ','আদম (আ.)-এর দোয়া','হে আমাদের রব, আমরা নিজেদের প্রতি জুলুম করেছি। আপনি যদি আমাদের ক্ষমা না করেন ও দয়া না করেন, তবে আমরা অবশ্যই ক্ষতিগ্রস্তদের অন্তর্ভুক্ত হব।','حضرت آدم کی دعا','اے ہمارے رب، ہم نے اپنی جانوں پر ظلم کیا۔ اگر تو ہمیں نہ بخشے اور ہم پر رحم نہ کرے تو ہم ضرور نقصان اٹھانے والوں میں ہوں گے۔','دعاء آدم عليه السلام'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a03','أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ','সন্ধ্যার দোয়া','আমরা সন্ধ্যায় উপনীত হয়েছি এবং এই সন্ধ্যাতেও সার্বভৌমত্ব আল্লাহর।','شام کی دعا','ہم نے شام پائی اور شام کو بھی بادشاہی اللہ ہی کے لیے ہے۔','دعاء المساء'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a01','أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ','সকালের দোয়া','আমরা সকালে উপনীত হয়েছি এবং এই সকালেও সার্বভৌমত্ব আল্লাহর। সমস্ত প্রশংসা আল্লাহর। আল্লাহ ছাড়া কোনো উপাস্য নেই, তিনি এক, তাঁর কোনো শরিক নেই। সার্বভৌমত্ব তাঁরই, সমস্ত প্রশংসাও তাঁরই। তিনি সব কিছুর ওপর ক্ষমতাবান।','صبح کی دعا','ہم نے صبح پائی اور صبح کو بھی بادشاہی اللہ کے لیے ہے۔ سب تعریف اللہ کے لیے ہے۔ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں۔ بادشاہی اسی کی اور سب تعریف اسی کے لیے ہے، اور وہ ہر چیز پر قدرت رکھتا ہے۔','دعاء الصباح'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a20','أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ','সকালে আশ্রয় চাওয়া','আল্লাহ যা সৃষ্টি করেছেন তার অনিষ্ট থেকে আমি তাঁর পরিপূর্ণ বাণীসমূহের আশ্রয় চাই।','صبح پناہ مانگنا','میں اللہ کی مخلوق کے شر سے اس کے کامل کلمات کی پناہ مانگتا ہوں۔','الاستعاذة في الصباح'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a02','اللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ','সকালে আল্লাহর আশ্রয়ের দোয়া','হে আল্লাহ, আপনারই অনুগ্রহে আমরা সকালে ও সন্ধ্যায় উপনীত হই। আপনারই ইচ্ছায় আমরা বাঁচি ও মরি, আর পুনরুত্থানের পর আপনারই কাছে ফিরব।','صبح کی حفاظت کی دعا','اے اللہ، تیرے ہی سہارے ہم صبح کرتے ہیں اور شام کرتے ہیں، تیرے ہی حکم سے جیتے اور مرتے ہیں، اور دوبارہ اٹھ کر تیری ہی طرف جانا ہے۔','دعاء الصباح والمساء'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a04','اللَّهُمَّ بِكَ أَمْسَيْنَا','সন্ধ্যায় আল্লাহর আশ্রয়ের দোয়া','হে আল্লাহ, আপনারই অনুগ্রহে আমরা সন্ধ্যায় উপনীত হয়েছি।','شام کی حفاظت کی دعا','اے اللہ، تیرے ہی سہارے ہم نے شام پائی۔','دعاء المساء'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a13','اللَّهُمَّ اغْفِرْ لِي','ক্ষমা প্রার্থনা','হে আল্লাহ, আমাকে ক্ষমা করুন।','بخشش طلب کرنا','اے اللہ، مجھے بخش دے۔','طلب المغفرة'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a19','اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ كُلِّ دَابَّةٍ أَنْتَ آخِذٌ بِنَاصِيَتِهَا','অনিষ্ট থেকে আশ্রয়ের দোয়া','হে আল্লাহ, আমার নিজের অনিষ্ট থেকে এবং প্রত্যেক প্রাণীর অনিষ্ট থেকে আমি আপনার আশ্রয় চাই, যার কপালের চুল আপনার হাতে।','شر سے پناہ کی دعا','اے اللہ، میں اپنے نفس کے شر سے اور ہر اس جاندار کے شر سے تیری پناہ مانگتا ہوں جس کی پیشانی تیرے قبضے میں ہے۔','الاستعاذة من الشر'),
('b0eebc99-9c0b-4ef8-bb6d-6bb9bd380a07','سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا','সফরের দোয়া','পবিত্র তিনি, যিনি এটি আমাদের বশীভূত করে দিয়েছেন।','سفر کی دعا','پاک ہے وہ جس نے اسے ہمارے تابع کر دیا۔','دعاء السفر')
) INSERT INTO public.dua_translations(dua_id,locale,title,translation,source,reviewed)
SELECT d.id,t.locale,t.title,t.meaning,t.source,t.reviewed
FROM catalog c JOIN public.duas d ON d.id=c.id::uuid AND d.arabic_text=c.arabic
CROSS JOIN LATERAL (VALUES
 ('ar',c.ar_title,d.arabic_text,'Original Arabic · ' || coalesce(d.reference,d.name),true),
 ('bn',c.bn_title,c.bn_text,'Muslim Sync · AI-assisted Bangla rendering of the Arabic excerpt',false),
 ('ur',c.ur_title,c.ur_text,'Muslim Sync · AI-assisted Urdu rendering of the Arabic excerpt',false)
) t(locale,title,meaning,source,reviewed)
ON CONFLICT (dua_id,locale) DO NOTHING;
WITH labels(slug,bn,ar,ur) AS (VALUES ('morning','সকালের দোয়া','أذكار الصباح','صبح کی دعائیں'),('evening','সন্ধ্যার দোয়া','أذكار المساء','شام کی دعائیں'),('food','খাবার ও পানীয়','الطعام والشراب','کھانا اور پینا'),('travel','সফর','السفر','سفر'),('sleep','ঘুম','النوم','نیند'),('rizq','রিজিকের দোয়া','أدعية الرزق','رزق کی دعائیں'),('forgiveness','ক্ষমার দোয়া','أدعية المغفرة','بخشش کی دعائیں'),('health','সুস্থতার দোয়া','أدعية العافية','عافیت کی دعائیں'),('protection','সুরক্ষার দোয়া','أدعية الحفظ','حفاظت کی دعائیں'),('guidance','হিদায়াতের দোয়া','أدعية الهداية','ہدایت کی دعائیں'))
INSERT INTO public.dua_category_translations(category_id,locale,name,reviewed)
SELECT c.id,t.locale,t.name,true FROM labels l JOIN public.dua_categories c USING(slug)
CROSS JOIN LATERAL (VALUES ('ar',l.ar),('bn',l.bn),('ur',l.ur)) t(locale,name)
ON CONFLICT (category_id,locale) DO NOTHING;
COMMIT;
